  2140→/// Calculate the expected gas limit for a block.
  2141→pub fn expected_gas_limit(
  2142→    parent_gas_limit: u64,
  2143→    target_gas_limit: u64,
  2144→    spec: &ChainSpec,
  2145→) -> Option<u64> {
  2146→    // Calculate the maximum gas limit difference allowed safely
  2147→    let max_gas_limit_difference = parent_gas_limit
  2148→        .checked_div(spec.gas_limit_adjustment_factor)
  2149→        .and_then(|result| result.checked_sub(1))
  2150→        .unwrap_or(0);
  2151→
  2152→    // Adjust the gas limit safely
  2153→    if target_gas_limit > parent_gas_limit {
  2154→        let gas_diff = target_gas_limit.saturating_sub(parent_gas_limit);
  2155→        parent_gas_limit.checked_add(std::cmp::min(gas_diff, max_gas_limit_difference))
  2156→    } else {
  2157→        let gas_diff = parent_gas_limit.saturating_sub(target_gas_limit);
  2158→        parent_gas_limit.checked_sub(std::cmp::min(gas_diff, max_gas_limit_difference))
  2159→    }
  2160→}
